import{_ as a,o as e,c as i,ag as d}from"./chunks/framework.C9sp7nFj.js";const m=JSON.parse('{"title":"WaitCameraDCPOS 获取视觉目标位置","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/22. 飞拍指令/WaitCameraDCPOS.md","filePath":"3. 指令/22. 飞拍指令/WaitCameraDCPOS.md","lastUpdated":1778862643000}'),s={name:"3. 指令/22. 飞拍指令/WaitCameraDCPOS.md"};function r(n,t,h,l,o,p){return e(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="waitcameradcpos-获取视觉目标位置" tabindex="-1">WaitCameraDCPOS 获取视觉目标位置 <a class="header-anchor" href="#waitcameradcpos-获取视觉目标位置" aria-label="Permalink to &quot;WaitCameraDCPOS 获取视觉目标位置&quot;">​</a></h1><p>该指令用于获取视觉传输过来的目标相对位置。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>WaitCameraDCPOS(WTime, Vision, TP, tagID, Ret) WaitCameraDCPOS(等待时间, 相机索引号, 目标相对位置, 目标物体ID, 有效性)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>WTime</td><td>int</td><td>执行等待时所需的时间，单位为 ms。值为 0 时默认不等待。</td><td></td></tr><tr><td>Vision</td><td>int</td><td>相机索引号。</td><td></td></tr><tr><td>TP</td><td>DCPOS 变量</td><td>目标相对位置，相对于参考位置的位置增量。</td><td></td></tr><tr><td>tagID</td><td>INT</td><td>目标物体的 ID 值。</td><td></td></tr><tr><td>Ret</td><td>INT</td><td>获取的目标相对位置是否有效。返回 1 表示成功，0 表示无效，-1 表示未获取到偏移点超时退出，-2 表示当前超时时间为 0 且未获取到偏移点。</td><td></td></tr></tbody></table><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WaitCameraDCPOS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, DCPOS0, INT0, INT1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析</strong>： 循环等待 10 秒，直到获取到相机传输的目标相对位置。</p>',10)])])}const C=a(s,[["render",r]]);export{m as __pageData,C as default};
